const email = $input.item.json;
const rawBody = email.text || email.html || '';
const body = rawBody.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 2000);

let fromStr = '';
if (typeof email.from === 'string') {
  fromStr = email.from;
} else if (email.from && email.from.value && Array.isArray(email.from.value)) {
  fromStr = email.from.value.map(v => v.name ? v.name + ' <' + v.address + '>' : v.address).join(', ');
} else if (email.from && email.from.text) {
  fromStr = email.from.text;
}

return {
  json: {
    from: fromStr,
    subject: email.subject || '(no subject)',
    body: body,
    date: email.date || new Date().toISOString()
  }
};

const resp = $input.item.json;
const prev = $('Extract Fields').first().json;
let parsed;
try {
  parsed = JSON.parse(resp.choices[0].message.content);
} catch(e) {
  parsed = { is_suspicious: false, reason: 'parse error' };
}
return {
  json: {
    from: prev.from,
    subject: prev.subject,
    body: prev.body,
    date: prev.date,
    is_suspicious: !!parsed.is_suspicious,
    injection_reason: parsed.reason || ''
  }
};

const resp = $input.item.json;
const prev = $('Parse Injection').first().json;
let parsed;
try {
  parsed = JSON.parse(resp.choices[0].message.content);
} catch(e) {
  parsed = { category: 'fyi', summary: 'Classification failed', should_draft_reply: false, suggested_reply_intent: '' };
}
return {
  json: {
    from: prev.from,
    subject: prev.subject,
    body: prev.body,
    date: prev.date,
    category: parsed.category || 'fyi',
    summary: parsed.summary || '',
    should_draft_reply: !!parsed.should_draft_reply,
    suggested_reply_intent: parsed.suggested_reply_intent || ''
  }
};

